<script setup>
import { ref } from 'vue'
import { newId, save, state } from '../stores/lexigo'
const groupName = ref(''); const add = () => { if (!groupName.value.trim()) return; state.groups.push({ id: newId('group'), name: groupName.value.trim(), students: [] }); groupName.value = ''; save() }; const remove = (group) => { if (confirm(`Remove ${group.name}?`)) { state.groups = state.groups.filter((item) => item.id !== group.id); save() } }; const packagesFor = (group) => state.packages.filter((pkg) => pkg.groupId === group.id).length
</script>
<template><section class="mx-auto max-w-5xl px-5 py-14"><p class="text-[11px] font-bold tracking-[.15em] text-lexi">LEARNING GROUPS</p><h1 class="mt-2 font-display text-5xl font-bold">My groups</h1><p class="mt-2 text-slate-500">Keep your classes and their vocabulary in sync.</p><form class="mt-7 flex max-w-lg gap-3" @submit.prevent="add"><input v-model="groupName" class="w-full rounded-xl border border-slate-200 bg-white px-3 py-3 outline-lexi" placeholder="Name a new group"><button class="shrink-0 rounded-xl bg-lexi px-4 py-3 text-sm font-bold text-white">Add group</button></form><div class="mt-8 grid gap-4 sm:grid-cols-2"><article v-for="group in state.groups" :key="group.id" class="flex items-center gap-4 rounded-2xl border border-slate-200 bg-white p-5"><span class="grid h-12 w-12 place-items-center rounded-xl bg-lexi font-display text-2xl font-bold text-white">{{ group.name[0] }}</span><div><h2 class="font-display text-2xl font-bold">{{ group.name }}</h2><p class="text-sm text-slate-500">{{ group.students.length }} learners · {{ packagesFor(group) }} packages</p></div><button class="ml-auto text-xl text-slate-400 hover:text-rose-600" @click="remove(group)">×</button></article></div></section></template>
